package glitch

import data.glitch_lib

# Credential-related keywords for field names
credential_keywords := {
    "password", "passwd", "pwd", "secret", "secret_key", "api_key", "token",
    "auth_token", "access_key", "credential", "login_password", "root_password",
    "admin_password", "database_password", "db_password"
}

# Default password values to detect
default_passwords := {
    "password", "admin", "123456", "12345678", "qwerty", "default", "changeme",
    "secret", "password123", "admin123", "test", "test123", "guest", "root",
    "toor", "letmein", "welcome", "passwort", "pass", "login", "user"
}

# Check if attribute name matches credential pattern
is_credential_field(name) {
    lower_name := lower(name)
    lower_name == credential_keywords[_]
}

is_credential_field(name) {
    lower_name := lower(name)
    endswith(lower_name, "_password")
}

is_credential_field(name) {
    lower_name := lower(name)
    endswith(lower_name, "_secret")
}

is_credential_field(name) {
    lower_name := lower(name)
    endswith(lower_name, "_key")
}

is_credential_field(name) {
    lower_name := lower(name)
    and{endswith(lower_name, "_token"), not endswith(lower_name, "_count")}
}

# Check if string value is likely a hardcoded password (not a variable reference or empty)
is_hardcoded_password(value) {
    value.ir_type == "String"
    count(value.value) > 0
    not is_variable_reference_only(value.value)
}

# Check if value contains only variable references (should skip these)
is_variable_reference_only(str) {
    regex.match("^\\$\\{[^}]+\\}$", str)
}

is_hardcoded_password(value) {
    value.ir_type == "Integer"
    value.value > 0
}

# Check if value is a suspicious default password
is_suspicious_default(value) {
    value.ir_type == "String"
    lower_value := lower(value.value)
    lower_value == default_passwords[_]
}

# Recursively check for String values in complex structures that might be hardcoded passwords
contains_string_literal(node) {
    node.ir_type == "String"
    count(node.value) > 0
    not is_variable_reference_only(node.value)
}

contains_string_literal(node) {
    node.ir_type == "Hash"
    some key, val
    val = node.value[key]
    contains_string_literal(val)
}

contains_string_literal(node) {
    node.ir_type == "Array"
    some i
    contains_string_literal(node.value[i])
}

# Check if parent context indicates authentication/credential usage
is_auth_context(parent_node) {
    parent_node.ir_type == "AtomicUnit"
    lower_type := lower(parent_node.type)
    contains(lower_type, {"auth", "login", "credential", "user", "account", "identity"})
}

has_auth_sibling(attrs, current_attr) {
    some other_attr
    other_attr := attrs[_]
    other_attr != current_attr
    is_credential_field(other_attr.name)
}

# Check for connection string with embedded credentials
is_connection_string_with_creds(name, value) {
    lower_name := lower(name)
    contains(lower_name, {"connection_string", "conn_string", "dsn", "uri", "url", "endpoint"})
    value.ir_type == "String"
    # Look for common credential patterns in URLs
    regex.match("(?i)(://[^/]*:[^@]*@|password=|pwd=|pass=)", value.value)
}

# Main detection: direct hardcoded password in credential field
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check attributes in atomic units
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    is_credential_field(attr.name)
    is_hardcoded_password(attr.value)

    # Ensure it's not using variable reference for the actual value
    not is_var_ref_or_func_call(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded password - Avoid using hard-coded passwords in configuration files. Use secret management systems instead. (CWE-259)"
    }
}

# Detection: suspicious default password values
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    is_credential_field(attr.name)
    is_suspicious_default(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded password - Avoid using weak or default hard-coded passwords. Use secret management systems instead. (CWE-259)"
    }
}

# Detection: connection strings with embedded credentials
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

