is_vault_or_secret_manager(value) {
    value.ir_type == "String"
    regex.match("(?i)(vault|secrets?_manager|secretsmanager|key_vault|secret_manager|terraform\\.io|data\\.aws_|data\\.azurerm_|lookup\\()", value.value)
}

